"""Generated exact-device Ampere greedy-tail authorities for model vocabularies."""

from __future__ import annotations

from functools import lru_cache
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
from typing import Any, Mapping

from kestrel_kernels.sampling.greedy_tail_config import (
    AmpereGreedyTailCalibrationUnavailable,
    AmpereGreedyTailTarget,
    GreedyTailConfig,
    GREEDY_TAIL_AMPERE_SEARCH_SPACE,
    GREEDY_TAIL_BATCH_CAPACITIES,
    GREEDY_TAIL_REQUIRED_CASES,
    _SHIPPING_SOURCE_IDENTITIES,
    _SOURCE_CONTRACT_SECTIONS,
    _available_shipping_source_identities,
    _fake_tensor_provider_identity,
    _fake_tensor_provider_path,
    ampere_greedy_tail_target_for_device,
    derive_greedy_tail_selection,
    derive_greedy_tail_summary,
    greedy_tail_runtime_launch_contract_sha256,
)
from kestrel_kernels.source_identity import semantic_python_symbol_closure_bytes


_TIMING_SOURCE_IDENTITIES = frozenset(
    {
        "config_module_sha256",
        "derivation_provider_sha256",
        "kernel_sha256",
        "runner_sha256",
        "common_runner_provider_sha256",
        "device_compile_contract_sha256",
        "compile_provider_sha256",
        "fake_tensor_provider_sha256",
        "runtime_launch_contract_sha256",
        "target_identity_provider_sha256",
    }
)


def authority_filename(target: AmpereGreedyTailTarget) -> str:
    return f"greedy_tail_scope_ampere_{target.key}.json"


def _source_paths() -> dict[str, tuple[Path, tuple[str, ...]]]:
    module_path = Path(__file__)
    source_root = module_path.resolve().parents[3]
    return {
        "config_module_sha256": (
            module_path,
            ("_validate_batch",),
        ),
        "derivation_provider_sha256": (
            module_path.with_name("greedy_tail_config.py"),
            (
                "GREEDY_TAIL_AMPERE_SEARCH_SPACE",
                "GREEDY_TAIL_REQUIRED_CASES",
                "ampere_greedy_tail_target_for_device",
                "derive_greedy_tail_selection",
                "derive_greedy_tail_summary",
            ),
        ),
        "kernel_sha256": (module_path.with_name("greedy_tail.py"), ("GreedyTail",)),
        "runner_sha256": (
            source_root / "scripts/tune_greedy_tail_ampere_scope.py",
            ("_candidate_timing",),
        ),
        "common_runner_provider_sha256": (
            source_root / "scripts/tune_greedy_tail.py",
            (
                "_atomic_write",
                "_correctness_gate",
                "_make_context",
                "_measure_independent",
                "_raw_operation",
                "_torch_operation",
            ),
        ),
        "device_compile_contract_sha256": (
            source_root / "scripts/precompile/cubin_bundles.py",
            ("_compile_cubin_device_contract",),
        ),
        "compile_provider_sha256": (
            source_root / "scripts/precompile/families/sampling.py",
            ("_compile_greedy_tail",),
        ),
        "target_identity_provider_sha256": (
            module_path.resolve().parents[1] / "arch.py",
            ("normalize_gpu_name_key",),
        ),
    }


def available_source_identities() -> dict[str, dict[str, str]]:
    timing = {
        name: hashlib.sha256(
            semantic_python_symbol_closure_bytes(path, symbols)
        ).hexdigest()
        for name, (path, symbols) in _source_paths().items()
        if path.is_file()
    }
    timing["runtime_launch_contract_sha256"] = (
        greedy_tail_runtime_launch_contract_sha256()
    )
    if _fake_tensor_provider_path() is not None:
        timing["fake_tensor_provider_sha256"] = _fake_tensor_provider_identity()
    return {
        "timing_contract": timing,
        "shipping_correctness_contract": _available_shipping_source_identities(),
    }


def _exact_json_value(actual: object, expected: object) -> bool:
    return json.dumps(actual, sort_keys=True, separators=(",", ":")) == json.dumps(
        expected, sort_keys=True, separators=(",", ":")
    )


def _validate_timing(value: object, *, label: str) -> None:
    if not isinstance(value, Mapping) or set(value) != {
        "samples_us",
        "independent_run_samples_us",
        "summary",
    }:
        raise RuntimeError(f"Ampere greedy-tail scope {label} timing is incomplete")
    samples = value["samples_us"]
    runs = value["independent_run_samples_us"]
    if (
        not isinstance(samples, list)
        or len(samples) != 9
        or any(
            not isinstance(sample, (int, float))
            or isinstance(sample, bool)
            or not math.isfinite(float(sample))
            or float(sample) <= 0
            for sample in samples
        )
        or not isinstance(runs, list)
        or len(runs) != 9
        or any(
            not isinstance(run, list)
            or len(run) != 3
            or any(
                not isinstance(sample, (int, float))
                or isinstance(sample, bool)
                or not math.isfinite(float(sample))
                or float(sample) <= 0
                for sample in run
            )
            for run in runs
        )
    ):
        raise RuntimeError(f"Ampere greedy-tail scope {label} samples are incomplete")
    medians = [statistics.median(run) for run in runs]
    if samples != medians or not _exact_json_value(
        value["summary"], derive_greedy_tail_summary(samples)
    ):
        raise RuntimeError(f"Ampere greedy-tail scope {label} timing is not derived")


def _validate_correctness(value: object, *, label: str) -> None:
    if (
        not isinstance(value, Mapping)
        or set(value) != set(GREEDY_TAIL_REQUIRED_CASES)
        or any(result is not True for result in value.values())
    ):
        raise RuntimeError(
            f"Ampere greedy-tail scope {label} correctness is incomplete"
        )


def _validate_batch(
    vocab_size: int,
    capacity: int,
    value: object,
) -> GreedyTailConfig:
    label = f"B{capacity}"
    if not isinstance(value, Mapping) or set(value) != {
        "vocab_size", "batch_capacity", "baseline", "candidates", "selection",
    }:
        raise RuntimeError(f"Ampere greedy-tail scope {label} evidence is incomplete")
    if value["vocab_size"] != vocab_size or value["batch_capacity"] != capacity:
        raise RuntimeError(f"Ampere greedy-tail scope {label} shape is not exact")
    baseline = value["baseline"]
    if (
        not isinstance(baseline, Mapping)
        or set(baseline) != {
            "identity",
            "samples_us",
            "independent_run_samples_us",
            "summary",
        }
        or baseline["identity"] != "torch_argmax_plus_index_copy"
    ):
        raise RuntimeError(f"Ampere greedy-tail scope {label} baseline is incomplete")
    _validate_timing(
        {name: baseline[name] for name in (
            "samples_us", "independent_run_samples_us", "summary"
        )},
        label=f"{label} baseline",
    )
    candidates = value["candidates"]
    expected = {
        f"t{threads}_s{splits}": (threads, splits)
        for threads, splits in GREEDY_TAIL_AMPERE_SEARCH_SPACE[capacity]
    }
    if not isinstance(candidates, Mapping) or set(candidates) != set(expected):
        raise RuntimeError(
            f"Ampere greedy-tail scope {label} candidate coverage is incomplete"
        )
    for identity, (threads, splits) in expected.items():
        candidate = candidates[identity]
        if (
            not isinstance(candidate, Mapping)
            or set(candidate) != {
                "threads", "splits", "correctness", "samples_us",
                "independent_run_samples_us", "summary",
            }
            or candidate["threads"] != threads
            or candidate["splits"] != splits
        ):
            raise RuntimeError(
                f"Ampere greedy-tail scope {label} candidate {identity} is incomplete"
            )
        _validate_correctness(candidate["correctness"], label=f"{label} {identity}")
        _validate_timing(
            {name: candidate[name] for name in (
                "samples_us", "independent_run_samples_us", "summary"
            )},
            label=f"{label} {identity}",
        )
    selection = derive_greedy_tail_selection(candidates)
    if not _exact_json_value(value["selection"], selection):
        raise RuntimeError(f"Ampere greedy-tail scope {label} selection is not derived")
    if selection["median_us"] >= baseline["summary"]["median_us"]:
        raise RuntimeError(f"Ampere greedy-tail scope {label} does not beat torch")
    return GreedyTailConfig(
        batch_capacity=capacity,
        vocab_size=0,
        num_threads=int(selection["threads"]),
        num_splits=int(selection["splits"]),
    )


def validate_ampere_greedy_tail_scope_artifact(
    artifact: object,
    *,
    target: AmpereGreedyTailTarget | None,
    require_current_sources: bool,
) -> tuple[GreedyTailConfig, ...]:
    if not isinstance(artifact, Mapping) or set(artifact) != {
        "schema_version", "target", "measurement", "source", "toolchain",
        "vocabularies",
    }:
        raise RuntimeError("Ampere greedy-tail scope authority is incomplete")
    raw_target = artifact["target"]
    try:
        artifact_target = ampere_greedy_tail_target_for_device(
            raw_target["gpu"], tuple(raw_target["capability"]), raw_target["num_sms"]
        )
    except (KeyError, TypeError):
        artifact_target = None
    if (
        artifact["schema_version"] != 1
        or artifact_target is None
        or not _exact_json_value(raw_target, {
            "key": artifact_target.key,
            "gpu": artifact_target.gpu,
            "capability": list(artifact_target.capability),
            "architecture": artifact_target.architecture,
            "num_sms": artifact_target.num_sms,
            "dtype": "bfloat16",
        })
        or (target is not None and artifact_target != target)
    ):
        raise RuntimeError("Ampere greedy-tail scope target is incomplete")
    measurement = artifact["measurement"]
    if not _exact_json_value(measurement, {
        "clock": "CUDA event elapsed time",
        "warmup_launches_per_operation": 200,
        "independent_runs": 9,
        "rounds_per_run": 3,
        "repeats_per_round": 128,
        "randomized_operation_order": True,
        "data_seed": 20260906,
        "measurement_seed_base": 20260906,
        "per_shape_seed_rule": "base + vocab_size + batch_capacity",
    }):
        raise RuntimeError("Ampere greedy-tail scope measurement is incomplete")
    source = artifact["source"]
    if (
        not isinstance(source, Mapping)
        or set(source) != _SOURCE_CONTRACT_SECTIONS
    ):
        raise RuntimeError("Ampere greedy-tail scope source identity is incomplete")
    for section, expected in (
        ("timing_contract", _TIMING_SOURCE_IDENTITIES),
        ("shipping_correctness_contract", _SHIPPING_SOURCE_IDENTITIES),
    ):
        values = source[section]
        if (
            not isinstance(values, Mapping)
            or set(values) != expected
            or any(
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
                for value in values.values()
            )
        ):
            raise RuntimeError("Ampere greedy-tail scope source identity is incomplete")
    if require_current_sources:
        available_sources = available_source_identities()
        if any(
            source["timing_contract"][name] != value
            for name, value in available_sources["timing_contract"].items()
        ):
            raise RuntimeError("Ampere greedy-tail scope authority is stale")
    toolchain = artifact["toolchain"]
    if (
        not isinstance(toolchain, Mapping)
        or not {"python", "torch", "cuda", "cutlass_dsl", "apache_tvm_ffi"}
        <= set(toolchain)
        or any(not isinstance(value, (str, int)) for value in toolchain.values())
    ):
        raise RuntimeError("Ampere greedy-tail scope toolchain is incomplete")
    vocabularies = artifact["vocabularies"]
    if not isinstance(vocabularies, Mapping) or not vocabularies:
        raise RuntimeError("Ampere greedy-tail scope vocabularies are incomplete")
    configs = []
    for raw_vocab, batches in vocabularies.items():
        if (
            not isinstance(raw_vocab, str)
            or re.fullmatch(r"[1-9][0-9]*", raw_vocab) is None
            or int(raw_vocab) % 8
            or not isinstance(batches, Mapping)
            or not batches
            or not set(batches) <= {
                str(capacity) for capacity in GREEDY_TAIL_BATCH_CAPACITIES
            }
        ):
            raise RuntimeError("Ampere greedy-tail scope vocabulary is malformed")
        vocab = int(raw_vocab)
        capacities = sorted(int(capacity) for capacity in batches)
        if capacities != sorted(set(capacities)):
            raise RuntimeError("Ampere greedy-tail scope capacities are malformed")
        for capacity in capacities:
            config = _validate_batch(vocab, capacity, batches[str(capacity)])
            configs.append(GreedyTailConfig(
                batch_capacity=config.batch_capacity,
                vocab_size=vocab,
                num_threads=config.num_threads,
                num_splits=config.num_splits,
            ))
    return tuple(sorted(configs, key=lambda config: (
        config.vocab_size, config.batch_capacity
    )))


@lru_cache(maxsize=None)
def load_ampere_greedy_tail_scope_configs(
    target: AmpereGreedyTailTarget,
    path: Path | None = None,
) -> tuple[GreedyTailConfig, ...]:
    authority_path = (
        Path(__file__).resolve().parents[1] / "configs" / authority_filename(target)
        if path is None else Path(path)
    )
    if not authority_path.is_file():
        raise AmpereGreedyTailCalibrationUnavailable(
            f"missing generated Ampere greedy-tail scope authority: {authority_path}"
        )
    return validate_ampere_greedy_tail_scope_artifact(
        json.loads(authority_path.read_text(encoding="utf-8")),
        target=target,
        require_current_sources=True,
    )


def load_ampere_greedy_tail_scope_inventory_configs(
    target: AmpereGreedyTailTarget,
    path: Path | None = None,
) -> tuple[GreedyTailConfig, ...]:
    """Load structurally derived scope rows for inventory declaration only."""

    authority_path = (
        Path(__file__).resolve().parents[1] / "configs" / authority_filename(target)
        if path is None else Path(path)
    )
    if not authority_path.is_file():
        raise AmpereGreedyTailCalibrationUnavailable(
            f"missing generated Ampere greedy-tail scope authority: {authority_path}"
        )
    return validate_ampere_greedy_tail_scope_artifact(
        json.loads(authority_path.read_text(encoding="utf-8")),
        target=target,
        require_current_sources=False,
    )


@lru_cache(maxsize=None)
def validate_ampere_greedy_tail_scope_shipping_sources(
    target: AmpereGreedyTailTarget, path: Path | None = None
) -> None:
    from kestrel_kernels.sampling.greedy_tail_config import (
        _validate_shipping_source_identities,
    )

    authority = (
        Path(__file__).resolve().parents[1] / "configs" / authority_filename(target)
        if path is None
        else Path(path)
    )
    artifact = json.loads(authority.read_text(encoding="utf-8"))
    validate_ampere_greedy_tail_scope_artifact(
        artifact, target=target, require_current_sources=False
    )
    _validate_shipping_source_identities(artifact["source"])


@lru_cache(maxsize=None)
def ampere_greedy_tail_scope_config_for_batch(
    batch: int,
    vocab_size: int,
    target: AmpereGreedyTailTarget,
) -> GreedyTailConfig | None:
    return next((
        config for config in load_ampere_greedy_tail_scope_configs(target)
        if config.vocab_size == vocab_size and batch <= config.batch_capacity
    ), None)


def load_ampere_greedy_tail_model_scope_configs(
    target: AmpereGreedyTailTarget,
) -> tuple[GreedyTailConfig, ...]:
    """Keep legacy Qwen authority and append generated non-default vocabularies."""

    from kestrel_kernels.sampling.greedy_tail_config import (
        GREEDY_TAIL_VOCAB_SIZE,
        load_ampere_greedy_tail_configs,
    )

    configs = list(load_ampere_greedy_tail_configs(target))
    try:
        scoped = load_ampere_greedy_tail_scope_configs(target)
    except AmpereGreedyTailCalibrationUnavailable:
        scoped = ()
    configs.extend(
        config for config in scoped if config.vocab_size != GREEDY_TAIL_VOCAB_SIZE
    )
    return tuple(configs)
